import sys,random
sys.path.insert(0,'/workspace/project')
import importlib
from modules import byte_program as bp
importlib.reload(bp)
from modules.byte_program import *
random.seed(7)
def build(depth=0):
    r=random.random()
    if depth>3 or r<0.35:
        return literal(bytes(random.randrange(256) for _ in range(random.randrange(0,20))))
    if r<0.6:
        return concat(build(depth+1),build(depth+1))
    if r<0.8:
        return repeat(build(depth+1),random.randrange(0,6))
    node=build(depth+1)
    lo=random.randrange(0,node.length+1); hi=random.randrange(lo,node.length+1)
    return cut(node,lo,hi)
ok=True
for trial in range(600):
    n=build()
    raw=materialize(n, 10**9)
    if n.length!=len(raw) or n.hash!=hash_bytes(raw): print('MISMATCH whole'); ok=False;break
    for _ in range(12):
        if not raw: continue
        lo=random.randrange(0,len(raw)); hi=random.randrange(lo,len(raw)+1)
        ln,h=hash_range(n,lo,hi)
        if ln!=hi-lo or h!=hash_bytes(raw[lo:hi]):
            print('MISMATCH range',lo,hi); ok=False; break
        if window(n,lo,hi)!=raw[lo:hi]: print('MISMATCH window'); ok=False;break
        for p in range(lo,hi):
            if byte_at(n,p)!=raw[p]: print('MISMATCH byte',p); ok=False;break
    if not ok: break
print('all ok' if ok else 'FAILED')
n=repeat(literal(b'ab'),10**11)
print([hex(x) for x in hash_range(n,3,10**11*2-1)])
print(hex(hash_range(n,0,n.length)[1]), hex(n.hash))
EOF
